import type { Journey, JourneyStop, Person } from './jiangshan.ts';
import type { I18n, LonLat, Year } from './types.ts';

/**
 * Curated journeys (人物行迹) that complement the imported ones so every era band, from the first humans to the
 * People's Republic, has at least one traveller to follow. Stops quote the classic sources where the wording is
 * well attested (史记, 汉书, 后汉书, 佛国记, 长春真人西游记, 马可·波罗行纪, 徐霞客游记 …). Journey `dyn` values are era ids.
 */
type T = readonly [string, string];
const L = (t: T): I18n => ({ zh: t[0], en: t[1] });

interface StopOpt { via?: LonLat[]; from?: LonLat }
const st = (year: Year, era: T, name: T, modern: T, [lon, lat]: LonLat, title: T, desc: T, quote?: T | null, o: StopOpt = {}): JourneyStop => ({
  year, era: L(era), name: L(name), modern: L(modern), lon, lat, title: L(title), desc: L(desc),
  ...(quote ? { quote: L(quote) } : {}), ...o,
});
const jr = (id: string, dyn: string, color: string, short: T, title: T, span: T, stops: JourneyStop[], person?: string): Journey => ({
  id, dyn, color, short: L(short), title: L(title), span: L(span), stops, ...(person ? { person } : {}),
});
const pp = (id: string, name: T, title: T, dyn: string, span: [Year, Year], aliases: string[] = []): Person => ({
  id, name: L(name), title: L(title), dyn, span, aliases, tokens: [name[0], ...aliases],
});

